import json

with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

nodes = data['pipeline_nodes']['data']
edges = data['pipeline_edges']['data']

lane_map = {
    'dev': 'Dev',
    'staging': 'Staging',
    'canary': 'Canary',
    'production': 'Production (Blue/Green)',
    'global': 'Global Actions'
}

lanes = {k: [] for k in lane_map.keys()}
for n in nodes:
    lanes[n['lane']].append(n)

mermaid_lines = []
mermaid_lines.append("flowchart LR")
mermaid_lines.append("    classDef action fill:#0f172a,stroke:#3b82f6,color:#fff,stroke-width:2px,rx:4,ry:4")
mermaid_lines.append("    classDef check fill:#0f172a,stroke:#8b5cf6,color:#fff,stroke-width:2px,rx:12,ry:12")
mermaid_lines.append("    classDef decision fill:#0f172a,stroke:#f59e0b,color:#fff,stroke-width:2px,rx:0,ry:0")
mermaid_lines.append("    classDef hpa_decision fill:#0f172a,stroke:#0ea5e9,color:#fff,stroke-width:2px,rx:0,ry:0")
mermaid_lines.append("    classDef hpa_action fill:#0284c7,stroke:#075985,color:#fff,stroke-width:2px,rx:4,ry:4")
mermaid_lines.append("    classDef rollback fill:#4c0519,stroke:#e11d48,color:#fecdd3,stroke-width:2px,rx:4,ry:4")
mermaid_lines.append("    classDef terminal fill:#064e3b,stroke:#10b981,color:#a7f3d0,stroke-width:2px,rx:4,ry:4")
mermaid_lines.append("    classDef blueGreen fill:#134e4a,stroke:#14b8a6,color:#ccfbf1,stroke-width:2px,rx:4,ry:4")
mermaid_lines.append("    classDef default fill:#1e293b,stroke:#475569,color:#f8fafc")

def clean_label(label):
    return label.replace('"', "'")

def get_node_str(n):
    label = clean_label(n['label'])

    details = []
    if 'cpu_threshold_pct' in n:
        details.append(f"CPU: {n['cpu_threshold_pct']}%")
    if 'mem_threshold_pct' in n:
        details.append(f"Mem: {n['mem_threshold_pct']}%")
    if 'error_rate_threshold_pct' in n:
        details.append(f"Err: {n['error_rate_threshold_pct']}%")
    if 'p99_latency_ms_threshold' in n and n['p99_latency_ms_threshold']:
        details.append(f"p99: {n['p99_latency_ms_threshold']}ms")
    if 'traffic_pct' in n:
        details.append(f"Traffic: {n['traffic_pct']}%")
    if 'duration_min' in n:
        details.append(f"Time: {n['duration_min']}m")

    if details:
        label += f"<br/><small>({' | '.join(details)})</small>"

    shape_start = "["
    shape_end = "]"

    if n['type'] in ['decision', 'hpa_decision']:
        shape_start = "{{"
        shape_end = "}}"
    elif n['type'] == 'check':
        shape_start = "(["
        shape_end = "])"

    # Assign specific classes
    cls = n['type']
    if 'blue-green' in n['id'] or 'blue_green' in n['type'] or 'green' in n['id'].lower() or 'blue' in n['id'].lower():
        cls = 'blueGreen'
    if 'hpa' in n['id'].lower() and cls not in ['hpa_decision', 'hpa_action']:
        cls = 'hpa_action'

    return f"    {n['id']}{shape_start}\"`{label}`\"{shape_end}:::{cls}"

for lane_id, lane_name in lane_map.items():
    mermaid_lines.append(f"    subgraph {lane_id} [\"{lane_name}\"]")
    mermaid_lines.append("        direction LR")
    for n in lanes[lane_id]:
        mermaid_lines.append("    " + get_node_str(n))
    mermaid_lines.append("    end")

# Edges
edge_idx = 0
for e in edges:
    label = e['label']
    arrow = "-->"
    if e['type'] == 'rollback':
        arrow = "-.->"
    elif e['type'] == 'blue_green':
        arrow = "==>"

    if label:
        line = f"    {e['from']} {arrow} |\"{label}\"| {e['to']}"
    else:
        line = f"    {e['from']} {arrow} {e['to']}"
    mermaid_lines.append(line)

    if e['type'] == 'rollback':
        mermaid_lines.append(f"    linkStyle {edge_idx} stroke:#e11d48,stroke-width:2px,stroke-dasharray: 5 5,color:#fecdd3")
    elif e['type'] == 'blue_green':
        mermaid_lines.append(f"    linkStyle {edge_idx} stroke:#14b8a6,stroke-width:3px,color:#ccfbf1")
    elif e['type'] == 'hpa_branch':
        mermaid_lines.append(f"    linkStyle {edge_idx} stroke:#0ea5e9,stroke-width:2px,stroke-dasharray: 3 3,color:#bae6fd")
    else:
        mermaid_lines.append(f"    linkStyle {edge_idx} stroke:#64748b,stroke-width:2px,color:#94a3b8")

    edge_idx += 1

with open('/app/tmp_mermaid.txt', 'w') as f:
    f.write("\n".join(mermaid_lines))
print("Mermaid LR generated!")
EOF
